        std::unordered_map<uint32, uint32> ritualHoldUntilMs;
        // [dmw-guard-body-pull] (party seq, guard guid) -> careful refusals of a pending door guard.
        std::map<std::pair<uint32, ObjectGuid>, uint32> guardRefusals;
