        constexpr bool ROUTE_LONG_REVERSE = true;
        constexpr bool ROUTE_BACKBONE_COMPLETE_ONLY = true;
        constexpr bool ROUTE_APPROACH_TO_SIGHT = true;
        constexpr bool ROUTE_LOG_TANK_REJECTS = true;
